    99  static void init_request(struct st_h2o_http1_conn_t *conn)
   100  {
   101      if (conn->_req_index != 0)
   102          h2o_dispose_request(&conn->req);
   103      h2o_init_request(&conn->req, &conn->super, NULL);
   104
   105      ++conn->_req_index;
   106      conn->req._ostr_top = &conn->_ostr_final.super;
   107      conn->_ostr_final.super.do_send = finalostream_send;
   108      conn->_ostr_final.super.start_pull = finalostream_start_pull;
   109      conn->_ostr_final.sent_headers = 0;
   110  }
