   122  static void set_timeout(struct st_h2o_http1_conn_t *conn, h2o_timeout_t *timeout, h2o_timeout_cb cb)
   123  {
   124      if (conn->_timeout != NULL) {
   125          h2o_timeout_unlink(&conn->_timeout_entry);
   126          conn->_timeout_entry.cb = NULL;
   127      }
   128      conn->_timeout = timeout;
   129      if (timeout != NULL) {
   130          h2o_timeout_link(conn->super.ctx->loop, timeout, &conn->_timeout_entry);
   131          conn->_timeout_entry.cb = cb;
   132      }
   133  }
