   135  static void process_request(struct st_h2o_http1_conn_t *conn)
   136  {
   137      if (conn->sock->ssl == NULL && conn->req.upgrade.base != NULL && conn->super.ctx->globalconf->http1.upgrade_to_http2 &&
   138          conn->req.upgrade.len >= 3 && h2o_lcstris(conn->req.upgrade.base, 3, H2O_STRLIT("h2c")) &&
   139          (conn->req.upgrade.len == 3 ||
   140           (conn->req.upgrade.len == 6 && (memcmp(conn->req.upgrade.base + 3, H2O_STRLIT("-14")) == 0 ||
   141                                           memcmp(conn->req.upgrade.base + 3, H2O_STRLIT("-16")) == 0)))) {
   142          if (h2o_http2_handle_upgrade(&conn->req, conn->super.connected_at) == 0) {
   143              return;
   144          }
   145      }
   146      h2o_process_request(&conn->req);
   147  }
