   149  #define DECL_ENTITY_READ_SEND_ERROR_XXX(status_)                                                                                   \
   150      static void entity_read_send_error_##status_(struct st_h2o_http1_conn_t *conn, const char *reason, const char *body)           \
   151      {                                                                                                                              \
   152          conn->_req_entity_reader = NULL;                                                                                           \
   153          set_timeout(conn, NULL, NULL);                                                                                             \
   154          h2o_socket_read_stop(conn->sock);                                                                                          \
   155          conn->req.http1_is_persistent = 0;                                                                                         \
   156          conn->super.ctx->emitted_error_status[H2O_STATUS_ERROR_##status_]++;                                                       \
   157          h2o_send_error_generic(&conn->req, status_, reason, body, H2O_SEND_ERROR_HTTP1_CLOSE_CONNECTION);                          \
   158      }
