   401  static void send_bad_request(struct st_h2o_http1_conn_t *conn)
   402  {
   403      h2o_socket_read_stop(conn->sock);
   404      h2o_send_error_400(&conn->req, "Bad Request", "Bad Request", H2O_SEND_ERROR_HTTP1_CLOSE_CONNECTION);
   405  }
